WITH valid AS (SELECT *, LOWER(promo_code) AS promo_code_lower FROM promotions WHERE ends_on >= TO_DATE('2023-11-13') AND channel IS NOT NULL), matched AS (SELECT e.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM valid e LEFT JOIN promotions pr ON e.channel = pr.channel AND e.ends_on >= pr.starts_on AND e.ends_on < pr.ends_on + INTERVAL '7' DAY), scored AS (SELECT *, AVG(promotion_discount_pct) OVER (PARTITION BY channel ORDER BY promotion_discount_pct ASC, id ASC, promo_id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS promotion_discount_pct_avg_6, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY starts_on ASC, id ASC, promo_id ASC) AS row_seq FROM matched WHERE ends_on >= '2025-02-12'), base AS (SELECT id, channel, starts_on, ends_on, promo_code_lower, promo_id, promotion_promo_code, promotion_discount_pct, promotion_discount_pct_avg_6, row_seq, UPPER(promo_code) AS promo_code_upper, COALESCE(promotion_promo_code, 'DIRECT') AS resolved_promotion_promo_code FROM scored WHERE channel IS NOT NULL AND ends_on >= DATE '2023-11-08'), ranked AS (SELECT * FROM base QUALIFY RANK() OVER (PARTITION BY promotion_promo_code, channel ORDER BY promo_id ASC NULLS LAST) = 1), base_promotions AS (SELECT *, CAST(row_seq AS DOUBLE) AS row_seq_num FROM ranked WHERE channel IS NOT NULL AND row_seq >= 8) SELECT * FROM (SELECT promotion_promo_code, channel, row_seq FROM base_promotions) src PIVOT (SUM(row_seq) AS amount, COUNT(1) AS cnt FOR channel IN ('partner' AS partner, 'mobile' AS mobile, 'store' AS store))
